iotdata_field_clouds_t *const v = vv;
if (*bp + IOTDATA_CLOUDS_BITS > bb)
    return false;
v->clouds = dequantise_clouds(bits_read(buf, bb, bp, IOTDATA_CLOUDS_BITS));
