(void)label;
size_t s = *bp;
uint32_t r = bits_read(buf, bb, bp, IOTDATA_CLOUDS_BITS);
snprintf(dump->_dec_buf, sizeof(dump->_dec_buf), "%" PRIu8 " okta", dequantise_clouds(r));
n = dump_add(dump, n, s, IOTDATA_CLOUDS_BITS, r, dump->_dec_buf, "0..8 okta", "clouds");
return n;

